'use strict';
window.createPhoenixHome=function({tasks,engine,state,navigate,progressUI}){
 const home=document.querySelector('#whiteorchard-console'),host=home.querySelector('.cover');
 const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
 const panel=make('section',null,'home-selected scroll-r16 selected-scroll');panel.setAttribute('aria-label','Selected quest');
 const title=make('h2'),desc=make('p'),next=make('p'),count=make('p'),level=make('p'),warning=make('p',null,'risk-note'),actions=make('nav',null,'home-selected-actions');actions.setAttribute('aria-label','Selected quest actions');
 const links=['Open walkthrough','Open quest hub and nearby activities','Open this quest’s cluster map'].map((text,i)=>{const a=make('a',null,'home-action-tile');const img=make('img');img.alt='';img.src=['navigation-art-v26/action-walkthrough.webp','navigation-art-v26/action-quest-hub.webp','white-orchard-map.webp'][i];img.loading='lazy';a.append(img,make('span',text));return a;});actions.append(...links);panel.append(title,desc,next,count,level,warning,actions);host.after(panel);
 const hud=make('details',null,'home-hud scroll-r16 console-group');hud.append(make('summary','White Orchard · Journey HUD'));const categories=make('div',null,'home-hud-categories');hud.append(categories);const whole=make('details');whole.append(make('summary','Whole journey'),make('p','White Orchard is tracked here. Velen is not integrated into this overview. Other regions have no tracked totals in this build.'));hud.append(whole);panel.after(hud);
 const buckets=Object.fromEntries(['main','side','exploration','gwent'].map(k=>{const row=make('section'),label=make('label'),toggle=make('input');toggle.type='checkbox';toggle.checked=true;const output=make('p');label.append(toggle,document.createTextNode(' Show '+({main:'main story',side:'side quests and contracts',exploration:'exploration and treasure',gwent:'Gwent collection'}[k])));toggle.onchange=()=>output.hidden=!toggle.checked;row.append(label,output);categories.append(row);return[k,output];}));
 const fieldTools=make('div');fieldTools.dataset.regionalTools='whiteorchard';hud.after(fieldTools);
 const preparation=make('section',null,'home-preparation-tools scroll-r16 console-group');preparation.id='whiteorchard-preparation-tools';preparation.setAttribute('aria-label','Preparation and departure tools');preparation.append(make('h2','Preparation & departure'));fieldTools.after(preparation);
 const kit=make('nav',null,'home-selected-actions');kit.setAttribute('aria-label','Character preparation');
 for(const [label,href,src] of [['Character','#character','gwent-r15/ivo.webp'],['Gear & Diagrams','#character-gear','art-r13/q-viper-card.webp']]){
  const a=make('a',null,'home-action-tile'),img=make('img');img.src=src;img.alt='';a.href=href;a.append(img,make('span',label));kit.append(a);
 }
 preparation.append(kit);
 // Preserve the original resume control, replace the duplicate shelf with compact tools.
 home.querySelector('.shelf')?.setAttribute('hidden','');home.querySelector('.doors')?.setAttribute('hidden','');
 // Issue #4 (QA6 rule applied to warning persistence): classify the saved list before anything can write it.
 // absent -> empty list, writable; a readable array of records -> loaded, writable; anything else (unreadable JSON,
 // empty string, non-array, damaged entries) or a storage read failure -> kept unchanged, never written this session.
 function readList(storageKey,accept){let raw;try{raw=localStorage.getItem(storageKey);}catch{return {list:[],writable:false,status:'storage-unavailable'};}
  if(raw===null)return {list:[],writable:true,status:'absent'};
  try{const saved=JSON.parse(raw);if(Array.isArray(saved)&&saved.every(accept))return {list:saved,writable:true,status:'accepted'};}catch{}
  return {list:[],writable:false,status:'unreadable'};}
 function writeList(storageKey,read,list){if(!read.writable)return read.status==='storage-unavailable'?'unavailable':'blocked';try{localStorage.setItem(storageKey,JSON.stringify(list));return 'saved';}catch{return 'unavailable';}}
 function acceptPendingWarning(w){return !!w&&!Array.isArray(w)&&typeof w==='object'&&typeof w.id==='string'&&typeof w.quest==='string'&&['failed','unavailable'].includes(w.status)&&typeof w.text==='string'&&(w.href==null||(typeof w.href==='string'&&w.href.startsWith('#')));}
 const key='phoenix.whiteorchard.warningHistory.v1',historyRead=readList(key,r=>r&&typeof r==='object'&&typeof r.text==='string');let historyRecords=historyRead.list;
 const pendingKey='phoenix.whiteorchard.pendingWarnings.v1',pendingRead=readList(pendingKey,acceptPendingWarning);let pendingWarnings=pendingRead.list.filter(w=>tasks[w.quest]&&['failed','unavailable'].includes(w.status)&&typeof w.text==='string');
 function savePending(){writeList(pendingKey,pendingRead,pendingWarnings);}
 function prunePending(){pendingWarnings=pendingWarnings.filter(w=>engine.status(w.quest,state.progress)===w.status);savePending();}
 function queuePending(w){medallion.enqueueWarning({...w,isValid:()=>engine.status(w.quest,state.progress)===w.status,onAcknowledge(){pendingWarnings=pendingWarnings.filter(item=>item.id!==w.id);savePending();}});}
 let selected=history.state?.consoleQuest||Object.keys(tasks).find(id=>tasks[id].stages),medallion;
 function selectedFromHistory(){const id=history.state?.consoleQuest;if(id&&tasks[id])selected=id;}
 function paintPanel(){const v=window.PhoenixHomePanel.selectedQuestView(selected,engine,state.progress,tasks);panel.hidden=!v;if(!v)return;title.textContent=v.name;desc.textContent=v.description;next.textContent=v.label;count.textContent=v.legacy?'Earlier completion mark retained; individual objectives have not been verified.':'Objectives: '+v.counts.done+'/'+v.counts.total+(v.counts.optionalTotal?' · optional '+v.counts.optionalDone+'/'+v.counts.optionalTotal:'');level.textContent=v.level===null?'Suggested level not recorded':'Suggested level '+v.level;warning.hidden=!v.warning;warning.textContent=v.warning;const t=tasks[selected];links[0].href='#'+t.view+(t.stages&&state.stageByView[t.view]?'/'+state.stageByView[t.view]:'');links[1].href='#whiteorchard-tree/'+t.home+'/'+selected;links[2].href='#whiteorchard-map/cluster/'+t.home+'/'+selected;}
 function paintWarnings(){document.querySelectorAll('[data-page-warning-history]').forEach(e=>e.remove());const view=document.querySelector('.view:not([hidden])');if(!view)return;const path=location.hash||'#home',root=path.split('/')[0];const related=historyRecords.filter(r=>r.href&&(r.href===path||(r.href===root&&view.dataset.task)));if(!related.length)return;const box=make('details',null,'page-warning-history');box.dataset.pageWarningHistory='';box.append(make('summary','Acknowledged warnings for this guide'));related.forEach(r=>box.append(make('p',r.text)));(view.querySelector('.reading-panel')||view.querySelector('.scene-inner')||view).append(box);}
 function refresh(){paintPanel();const metrics=window.PhoenixHomeMetrics.derive(tasks,state.completed,engine,state.progress);for(const [k,out] of Object.entries(buckets)){const b=metrics[k];out.textContent=b.label+' · '+(b.unavailable?b.note:b.done+'/'+b.total);}const summary=hud.querySelector('summary');summary.textContent='White Orchard · Journey HUD';const compact=make('small',`Story ${metrics.main.done}/${metrics.main.total} · Side ${metrics.side.done}/${metrics.side.total} · Exploration ${metrics.exploration.done}/${metrics.exploration.total} · Gwent untracked`);summary.append(compact);paintWarnings();}
 medallion=window.createPhoenixMedallion({navigationOnly:()=>window.PhoenixSharedWalkthrough?.isShowing?.()===true,navigationCards:window.PhoenixConsole.navigationCards,decorateNavigation:window.PhoenixConsole.decorateNavigation,onNavigate:navigate,getUndoAvailable:()=>!!state.progressUndo,onUndo:()=>progressUI.undoLast(),history:historyRecords,onWarningHistory(records){historyRecords=records;const result=writeList(key,historyRead,records);paintWarnings();return result;}});
 window.__phoenixMedallion=medallion;prunePending();pendingWarnings.forEach(queuePending);
 document.addEventListener('phoenix:card-selected',e=>{if(e.target.closest('#whiteorchard-console')&&tasks[e.detail?.quest]){selected=e.detail.quest;paintPanel();}});
 window.addEventListener('phoenix:route-rendered',()=>{selectedFromHistory();refresh();});
 window.addEventListener('phoenix:progress-committed',e=>{medallion.signalUndoAvailable();const plan=e.detail.plan;[['failures','failed'],['closing','unavailable']].forEach(([list,status])=>(plan[list]||[]).forEach(q=>{const t=tasks[q];const w={id:status+':'+q+':'+Date.now(),quest:q,status,text:'Progress update recorded '+t.name+(status==='failed'?' as failed.':' as unavailable.'),href:'#'+t.view};pendingWarnings.push(w);savePending();queuePending(w);}));prunePending();medallion.reconcileWarnings();refresh();});
 window.addEventListener('phoenix:progress-undone',()=>{medallion.dismissQuickUndo();prunePending();medallion.reconcileWarnings();refresh();});
 refresh();return {refresh,medallion};
};
